def count_primes(n: int) -> int:
    """
    Returns the count of prime numbers less than or equal to n using the segmented sieve method.

    :param n: An integer representing the upper limit.
    :return: The count of prime numbers less than or equal to n.
    """
    if n < 2:
        return 0

    limit = int(n**0.5) + 1
    prime = [True] * limit
    prime[0] = prime[1] = False

    for start in range(2, limit):
        if prime[start]:
            for multiple in range(start*start, limit, start):
                prime[multiple] = False

    prime_numbers = [p for p in range(2, limit) if prime[p]]

    if n < limit:
        return sum(prime)

    low = limit
    high = 2 * limit
    count = len(prime_numbers)

    while low <= n:
        block = [True] * (limit)
        for p in prime_numbers:
            start = max(p*p, low + (p - low % p) % p)
            for j in range(start, high, p):
                block[j - low] = False

        count += sum(block[:n-low+1])

        low += limit
        high += limit

    return count

