            return sales[low]
        pivot_index = partition(low, high)
        if k == pivot_index:
            return sales[k]
        elif k < pivot_index:
            return quickselect(low, pivot_index - 1, k)
        else:
            return quickselect(pivot_index + 1, high, k)

    if n % 2 == 1:
        return quickselect(0, n - 1, n // 2)
    else:
        mid1 = quickselect(0, n - 1, n // 2 - 1)
        mid2 = quickselect(n // 2, n - 1, n // 2)
