def merge_dicts(*dicts):
    """
    Merges multiple dictionaries into a single dictionary. If a key exists in multiple dictionaries,
    the value from the last dictionary will overwrite the previous ones. Nested dictionaries are merged
    recursively.

    :param dicts: Variable number of dictionary arguments to be merged.
    :return: A single merged dictionary.
    """
    def recursive_merge(base, update):
        for key, value in update.items():
            if isinstance(value, dict) and key in base and isinstance(base[key], dict):
                recursive_merge(base[key], value)
            else:
                base[key] = value
        return base

    if not dicts:
        return {}

    merged_dict = dicts[0]
    for dictionary in dicts[1:]:
        merged_dict = recursive_merge(merged_dict, dictionary)

    return merged_dict

