def to_lowercase(c):
    """
    Convert a single character to lowercase if it's an uppercase letter.
    Handles both Latin and Greek alphabets.
    """
    if ord('A') <= ord(c) <= ord('Z'):
        return chr(ord(c) + (ord('a') - ord('A')))
    elif ord('Α') <= ord(c) <= ord('Ω'):  # Greek uppercase letters
        return chr(ord(c) + (ord('α') - ord('Α')))
    elif ord('Ά') <= ord(c) <= ord('Ώ'):  # Greek uppercase with tonos
        return chr(ord(c) + (ord('ά') - ord('Ά')))
    else:
        return c

