    """
    Compare two strings in a case-insensitive manner.
    Returns -1 if s1 < s2, 1 if s1 > s2, and 0 if they are equal.
    """
    i = 0
    while i < len(s1) and i < len(s2):
        c1 = to_lowercase(s1[i])
        c2 = to_lowercase(s2[i])
        if c1 < c2:
            return -1
        elif c1 > c2:
            return 1
        i += 1

    if len(s1) == len(s2):
        return 0
    elif len(s1) < len(s2):
        return -1
    else:
        return 1

