    """
    Validates if the given dictionary represents a valid Markov chain transition probabilities.

    Args:
    transition_probabilities (dict): A dictionary where keys are tuples of two integers (current_state, next_state)
                                     and values are floats representing the transition probabilities.

    Returns:
    bool: True if the dictionary is a valid representation of transition probabilities, False otherwise.
    """
    if not isinstance(transition_probabilities, dict):
        return False

    states = set()
    prob_sum = {}

    for (current_state, next_state), probability in transition_probabilities.items():
        if not (isinstance(current_state, int) and isinstance(next_state, int)):
            return False

        if not (isinstance(probability, float) and 0 <= probability <= 1):
            return False

        states.add(current_state)

        if current_state not in prob_sum:
            prob_sum[current_state] = 0
        prob_sum[current_state] += probability

    for p_sum in prob_sum.values():
        if not abs(p_sum - 1.0) < 1e-9:
            return False

    for state in states:
        if state not in prob_sum or not abs(prob_sum[state] - 1.0) < 1e-9:
