            while queue:
                vertex = queue.popleft()
                current_color = color[vertex]

                for neighbor, edge_exists in enumerate(graph[vertex]):
                    if edge_exists:
                        if color[neighbor] == -1:
                            color[neighbor] = 1 - current_color
                            queue.append(neighbor)
                        elif color[neighbor] == current_color:
